from fractions import Fraction
import json

def fractions(x):
    if x is None:return None
    if not isinstance(x,list) or len(x)!=2 or any(type(v) is not int for v in x) or x[1]<=0:raise ValueError
    return Fraction(*x)

def normalize(ident,value,field=""):
    if ident in {"F18","F20"} and isinstance(value,list):
        q=fractions(value)
        return [q.numerator,q.denominator]
    if isinstance(value,dict):return {k:normalize(ident,v,k) for k,v in value.items()}
    return value

def check_value(ident,name,actual,wanted,context=None):
    try:
        if ident!="F17":
            return json.dumps(normalize(ident,actual),sort_keys=True)==json.dumps(normalize(ident,wanted),sort_keys=True)
        d=context.get("request",context);base=bytes.fromhex(d["base"]);out=bytearray();cost=head=0
        if set(actual)!={"cost","ops"} or type(actual["cost"]) is not int or not isinstance(actual["ops"],list):return False
        for op in actual["ops"]:
            if set(op)=={"literal"}:
                literal=bytes.fromhex(op["literal"])
                if not literal:return False
                out.extend(literal);cost+=d["literal_header"]+len(literal)*d["literal_unit"]
            elif set(op)=={"copy"}:
                offset,size=op["copy"]
                if type(offset) is not int or type(size) is not int or offset<0 or size<d["min_copy"] or offset+size>len(base):return False
                out.extend(base[offset:offset+size]);cost+=d["copy_header"]+abs(offset-head)*d["seek_unit"];head=offset+size
            else:return False
        return cost==actual["cost"]==wanted["cost"] and out==bytes.fromhex(d["target"])
    except (KeyError,TypeError,ValueError,ArithmeticError):
        return False

def build_regions(request):
    'Accept the public floor request and return a dict with areas, neighbors, and start. areas is a list of positive integer free-cell areas indexed by region. neighbors is a parallel list of lists of (neighbor_index, fee) pairs representing legal crossings in both directions. start is the index containing entry. Every region is internally connected by zero-fee moves, every free cell belongs to exactly one region, and crossing edges preserve the stated fees and legal reachability. Regions may represent many cells to support large coordinate extents. Preserve half-open blocked rectangles, additive fees for overlapping walls, and closed crossings for null fees.\n\nLocal check: Use a 3 by 1 free floor entered at (0, 0), place two walls of fees 2 and 3 on the first shared side, and a null-fee wall on the second side. Assert exactly three area-1 regions irrespective of indexing, one bidirectional connection of fee 5 from start, and no route edge to the isolated region.'
    raise NotImplementedError

from runtime import build, read

def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    raise NotImplementedError

def load_payload(path):
    return read(path)

def build_component(root, contract):
    return build(root, contract, transform)

def fee_areas(regions):
    "Accept the region structure with areas, neighbors, and start. Return the public object with area_by_fee and unreachable. Sum region areas by their exact minimum total fee from start. Map keys are decimal strings. Count the full area of every unreachable region once.\n\nLocal check: Pass areas [4, 3, 2, 5] and start 0. Connect 0 to 1 with fee 1, 1 to 2 with fee 2, and 0 directly to 2 with fee 9 in both directions. Node 3 is isolated. Assert fee areas are {'0': 4, '1': 3, '3': 2} and unreachable is 5."
    raise NotImplementedError

