import unittest
from engines.analysis.access_costs import fee_areas


class TestFeeAreas(unittest.TestCase):
    def test_local_check(self):
        r = fee_areas({
            "areas": [4, 3, 2, 5],
            "neighbors": [[(1, 1), (2, 9)], [(0, 1), (2, 2)], [(1, 2), (0, 9)], []],
            "start": 0,
        })
        self.assertEqual(r, {"area_by_fee": {"0": 4, "1": 3, "3": 2}, "unreachable": 5})

    def test_single_region(self):
        r = fee_areas({"areas": [7], "neighbors": [[]], "start": 0})
        self.assertEqual(r, {"area_by_fee": {"0": 7}, "unreachable": 0})

    def test_all_unreachable_except_start(self):
        r = fee_areas({"areas": [1, 2], "neighbors": [[], []], "start": 0})
        self.assertEqual(r, {"area_by_fee": {"0": 1}, "unreachable": 2})


if __name__ == "__main__":
    unittest.main()
