def build_regions(request):
    width, height = request["size"]
    entry = tuple(request["entry"])
    blocked = request.get("blocked", [])
    walls = request.get("walls", [])

    # Free-cell membership. Blocked rectangles are half-open: cells whose
    # lower-left coordinates satisfy x0 <= x < x1 and y0 <= y < y1.
    blocked_cells = set()
    for rect in blocked:
        x0, y0, x1, y1 = rect
        for x in range(x0, x1):
            for y in range(y0, y1):
                blocked_cells.add((x, y))

    free_cells = set()
    for x in range(width):
        for y in range(height):
            if (x, y) not in blocked_cells:
                free_cells.add((x, y))

    # Fee for crossing each shared side. A wall is a zero-thickness segment on
    # cell boundaries. A horizontal wall (y0 == y1) blocks vertical crossings
    # across that boundary; a vertical wall (x0 == x1) blocks horizontal
    # crossings. Overlapping walls sum; a null fee closes the crossing.
    #
    # Key a crossing by the two cells it separates and the direction axis.
    # We store fees per boundary segment so overlapping walls accumulate.
    def side_key(cell_a, cell_b):
        # canonical ordering of the two cells
        return tuple(sorted((cell_a, cell_b)))

    crossing_fee = {}
    crossing_closed = set()

    for wall in walls:
        seg = wall["segment"]
        fee = wall["fee"]
        x0, y0, x1, y1 = seg
        if x0 == x1:
            # vertical wall at x = x0, spanning y0..y1
            x = x0
            for y in range(y0, y1):
                left = (x - 1, y)
                right = (x, y)
                if left in free_cells and right in free_cells:
                    key = side_key(left, right)
                    if fee is None:
                        crossing_closed.add(key)
                    else:
                        crossing_fee[key] = crossing_fee.get(key, 0) + fee
        elif y0 == y1:
            # horizontal wall at y = y0, spanning x0..x1
            y = y0
            for x in range(x0, x1):
                below = (x, y - 1)
                above = (x, y)
                if below in free_cells and above in free_cells:
                    key = side_key(below, above)
                    if fee is None:
                        crossing_closed.add(key)
                    else:
                        crossing_fee[key] = crossing_fee.get(key, 0) + fee
        else:
            raise ValueError("wall segment must be axis-aligned")

