{"engines/analysis/floor_regions.py": """"Build a region graph from a floor request.

A region is a maximal set of free cells connected by zero-fee moves. Regions
are connected by crossing edges whose fee is the sum of all wall fees covering
the shared side (null fee closes the crossing). This representation supports
large coordinate extents because regions aggregate many cells.
"""


def build_regions(request):
    width, height = request["size"]
    entry = tuple(request["entry"])
    blocked = request.get("blocked", [])
    walls = request.get("walls", [])

    # Free-cell membership. Blocked rectangles are half-open: cells whose
    # lower-left coordinates satisfy x0 <= x < x1 and y0 <= y < y1.
    blocked_cells = set()
    for rect in blocked:
        x0, y0, x1, y1 = rect
        for x in range(x0, x1):
            for y in range(y0, y1):
                blocked_cells.add((x, y))

    free_cells = set()
    for x in range(width):
        for y in range(height):
            if (x, y) not in blocked_cells:
                free_cells.add((x, y))

    # Fee for crossing each shared side. A wall is a zero-thickness segment on
    # cell boundaries. A horizontal wall (y0 == y1) blocks vertical crossings
    # across that boundary; a vertical wall (x0 == x1) blocks horizontal
    # crossings. Overlapping walls sum; a null fee closes the crossing.
    #
    # Key a crossing by the two cells it separates and the direction axis.
    # We store fees per boundary segment so overlapping walls accumulate.
    def side_key(cell_a, cell_b):
        # canonical ordering of the two cells
        return tuple(sorted((cell_a, cell_b)))

    crossing_fee = {}
    crossing_closed = set()

    for wall in walls:
        seg = wall["segment"]
        fee = wall["fee"]
        x0, y0, x1, y1 = seg
        if x0 == x1:
            # vertical wall at x = x0, spanning y0..y1
            x = x0
            for y in range(y0, y1):
                left = (x - 1, y)
                right = (x, y)
                if left in free_cells and right in free_cells:
                    key = side_key(left, right)
                    if fee is None:
                        crossing_closed.add(key)
                    else:
                        crossing_fee[key] = crossing_fee.get(key, 0) + fee
        elif y0 == y1:
            # horizontal wall at y = y0, spanning x0..x1
            y = y0
            for x in range(x0, x1):
                below = (x, y - 1)
                above = (x, y)
                if below in free_cells and above in free_cells:
                    key = side_key(below, above)
                    if fee is None:
                        crossing_closed.add(key)
                    else:
                        crossing_fee[key] = crossing_fee.get(key, 0) + fee
        else:
            raise ValueError("wall segment must be axis-aligned")

    # Union-find over free cells using zero-fee moves.
    parent = {cell: cell for cell in free_cells}

    def find(cell):
        root = cell
        while parent[root] != root:
            root = parent[root]
        while parent[cell] != cell:
            nxt = parent[cell]
            parent[cell] = root
            cell = nxt
        return root

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for cell in free_cells:
        x, y = cell
        for dx, dy in ((1, 0), (0, 1)):
            other = (x + dx, y + dy)
            if other not in free_cells:
                continue
            key = side_key(cell, other)
            if key in crossing_closed:
                continue
            if crossing_fee.get(key, 0) == 0:
                union(cell, other)

    # Assign region indices.
    region_index = {}
    regions = []
    for cell in free_cells:
        root = find(cell)
        if root not in region_index:
            region_index[root] = len(regions)
            regions.append([])
        regions[region_index[root]].append(cell)

    areas = [len(cells) for cells in regions]

    # Build neighbor edges from non-zero-fee crossings (and closed crossings
    # are simply absent, so no edge is created for them).
    cell_region = {}
    for idx, cells in enumerate(regions):
        for cell in cells:
            cell_region[cell] = idx

    neighbors = [[] for _ in regions]
    seen_edges = set()
    for cell in free_cells:
        x, y = cell
        for dx, dy in ((1, 0), (0, 1)):
            other = (x + dx, y + dy)
            if other not in free_cells:
                continue
            key = side_key(cell, other)
            if key in crossing_closed:
                continue
            fee = crossing_fee.get(key, 0)
            if fee == 0:
                continue
            ra = cell_region[cell]
            rb = cell_region[other]
            if ra == rb:
                continue
            edge = tuple(sorted((ra, rb)))
            if edge in seen_edges:
                continue
            seen_edges.add(edge)
            neighbors[ra].append((rb, fee))
            neighbors[rb].append((ra, fee))

    start = cell_region[entry]

    return {"areas": areas, "neighbors": neighbors, "start": start}
"}

